'use strict';

/**
 * Tiny in-process cache with tag-based invalidation.
 *
 * - entries: Map<key, value>
 * - tagIndex: Map<tag, Set<key>>
 *
 * invalidateTag(tag) removes every entry tagged with `tag` and cleans the
 * remaining tag references of those entries so nothing leaks.
 */
class TagCache {
  constructor() {
    this.entries = new Map();
    this.tagIndex = new Map();
  }

  get(key) {
    return this.entries.has(key) ? this.entries.get(key) : undefined;
  }

  has(key) {
    return this.entries.has(key);
  }

  set(key, value, tags = []) {
    // If the key already exists, drop its old tag memberships first.
    if (this.entries.has(key)) this.delete(key);
    this.entries.set(key, value);
    for (const tag of tags) {
      let keys = this.tagIndex.get(tag);
      if (!keys) {
        keys = new Set();
        this.tagIndex.set(tag, keys);
      }
      keys.add(key);
    }
    return this;
  }

  delete(key) {
    if (!this.entries.has(key)) return false;
    this.entries.delete(key);
    for (const keys of this.tagIndex.values()) keys.delete(key);
    return true;
  }

  /** Drop every entry carrying `tag`. Returns the number of evicted entries. */
  invalidateTag(tag) {
    const keys = this.tagIndex.get(tag);
    if (!keys || keys.size === 0) return 0;
    const victims = [...keys];
    for (const key of victims) this.delete(key); // delete() cleans tagIndex
    this.tagIndex.delete(tag);
    return victims.length;
  }

  clear() {
    this.entries.clear();
    this.tagIndex.clear();
  }
}

module.exports = { TagCache };

