'use strict';

const express = require('express');
const { TagCache } = require('./tag-cache');

// --- In-memory product store -------------------------------------------------
let nextId = 4;
const products = new Map([
  [1, { id: 1, name: 'Widget', category: 'A' }],
  [2, { id: 2, name: 'Gadget', category: 'B' }],
  [3, { id: 3, name: 'Gizmo', category: 'B' }],
]);

const cache = new TagCache();

function catTag(category) {
  return `cat:${category}`;
}

/**
 * Caching middleware for GET requests.
 * Key = method + url. Tags are supplied per-route via res.locals.cacheTags
 * (set before calling next(), so we compute them in a pre-step).
 */
function cacheMiddleware(routeTags) {
  return function (req, res, next) {
    if (req.method !== 'GET') return next();

    const tags = typeof routeTags === 'function' ? routeTags(req) : routeTags;
    const key = `${req.method} ${req.originalUrl}`;

    const hit = cache.get(key);
    if (hit !== undefined) {
      res.setHeader('X-Cache', 'hit');
      return res.status(200).json(hit);
    }

    res.setHeader('X-Cache', 'miss');
    const originalJson = res.json.bind(res);
    res.json = (body) => {
      // Only cache successful list responses.
      if (res.statusCode === 200) cache.set(key, body, tags(req));
      return originalJson(body);
    };
    next();
  };
}

/** Invalidate the given tags and record what was evicted. */
function invalidate(tags) {
  const invalidated = [];
  let evicted = 0;
  for (const tag of tags) {
    const n = cache.invalidateTag(tag);
    if (n > 0) {
      invalidated.push(tag);
      evicted += n;
    }
  }
  return { invalidated, evicted };
}

const app = express();
app.use(express.json());

// --- Cached reads ------------------------------------------------------------

// GET /products          -> tags ['products']
// GET /products?category -> tags ['products', 'cat:<category>']
app.get(
  '/products',
  cacheMiddleware((req) => {
    const tags = ['products'];
    if (req.query.category) tags.push(catTag(String(req.query.category)));
    return tags;
  }),
  (req, res) => {
    let list = [...products.values()];
    if (req.query.category) {
      list = list.filter((p) => p.category === req.query.category);
    }
    res.status(200).json({ data: list });
  }
);

// GET /products/:id is intentionally uncached to keep the demo focused.

// --- Mutations: invalidate 'products' + affected category tag(s) -------------

app.post('/products', (req, res) => {
  const { name, category } = req.body || {};
  if (!name || !category) {
    return res.status(400).json({ error: 'name and category are required' });
  }
  const product = { id: nextId++, name, category };
  products.set(product.id, product);
  const result = invalidate(['products', catTag(category)]);
  res.status(201).json({ data: product, ...result });
});

app.put('/products/:id', (req, res) => {
  const id = Number(req.params.id);
  const existing = products.get(id);
  if (!existing) return res.status(404).json({ error: 'not found' });

  const { name, category } = req.body || {};
  const updated = {
    ...existing,
    ...(name !== undefined && { name }),
    ...(category !== undefined && { category }),
  };
  products.set(id, updated);

  // If the category changed, both the old and new category caches are stale.
  const tags = ['products'];
  if (updated.category !== existing.category) {
    tags.push(catTag(existing.category), catTag(updated.category));
  } else {
    tags.push(catTag(updated.category));
  }
  const result = invalidate(tags);
  res.status(200).json({ data: updated, ...result });
});

app.delete('/products/:id', (req, res) => {
  const id = Number(req.params.id);
  const existing = products.get(id);
  if (!existing) return res.status(404).json({ error: 'not found' });
  products.delete(id);
  const result = invalidate(['products', catTag(existing.category)]);
  res.status(200).json({ data: existing, ...result });
});

module.exports = { app, cache, products };

