'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');

// Fresh module state per test file run: reset store + cache between tests.
const { app, cache } = require('../app');

async function startServer() {
  return new Promise((resolve) => {
    const server = app.listen(0, '127.0.0.1', () => resolve(server));
  });
}

function baseURL(server) {
  const { port, address } = server.address();
  return `http://${address}:${port}`;
}

test('tag-based invalidation: mutating category A only busts list + cat:A', async (t) => {
  const server = await startServer();
  t.after(() => server.close());
  const base = baseURL(server);

  const get = async (path) => {
    const res = await fetch(base + path);
    assert.equal(res.status, 200);
    return { header: res.headers.get('x-cache'), body: await res.json() };
  };

  // 1) Prime three cached variants.
  const firstList = await get('/products');
  assert.equal(firstList.header, 'miss');

  const firstA = await get('/products?category=A');
  assert.equal(firstA.header, 'miss');

  const firstB = await get('/products?category=B');
  assert.equal(firstB.header, 'miss');

  // Sanity: all three are now hits.
  assert.equal((await get('/products')).header, 'hit');
  assert.equal((await get('/products?category=A')).header, 'hit');
  assert.equal((await get('/products?category=B')).header, 'hit');

  // 2) Mutate a product in category A.
  const widgetId = firstList.body.data.find(
    (p) => p.category === 'A'
  ).id;
  const mutate = await fetch(`${base}/products/${widgetId}`, {
    method: 'PUT',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ name: 'Widget Pro' }),
  });
  assert.equal(mutate.status, 200);
  const mutateBody = await mutate.json();
  assert.ok(mutateBody.invalidated.includes('products'));
  assert.ok(mutateBody.invalidated.includes('cat:A'));
  assert.deepEqual(cache.get('GET /products'), undefined);

  // 3) List and category-A are stale -> miss; category-B untouched -> hit.
  const listAfter = await get('/products');
  assert.equal(listAfter.header, 'miss');
  assert.equal(listAfter.body.data.find((p) => p.id === widgetId).name, 'Widget Pro');

  const aAfter = await get('/products?category=A');
  assert.equal(aAfter.header, 'miss');

  const bAfter = await get('/products?category=B');
  assert.equal(bAfter.header, 'hit');
  // And the cached B payload was never evicted.
  assert.equal(bAfter.body.data.length, 2);

  // 4) Re-warm: everything is a hit again.
  assert.equal((await get('/products')).header, 'hit');
  assert.equal((await get('/products?category=A')).header, 'hit');
});

test('POST invalidates products + its own category tag only', async (t) => {
  const server = await startServer();
  t.after(() => server.close());
  const base = baseURL(server);

  const prime = async (path) =>
    (await fetch(base + path)).headers.get('x-cache');

  assert.equal(await prime('/products'), 'miss');
  assert.equal(await prime('/products'), 'hit');
  assert.equal(await prime('/products?category=C'), 'miss');
  assert.equal(await prime('/products?category=C'), 'hit');

  const res = await fetch(`${base}/products`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ name: 'Doohickey', category: 'C' }),
  });
  assert.equal(res.status, 201);

  assert.equal((await prime('/products')), 'miss');
  assert.equal((await prime('/products?category=C')), 'miss');
});

test('DELETE invalidates products + the deleted product category tag', async (t) => {
  const server = await startServer();
  t.after(() => server.close());
  const base = baseURL(server);

  const prime = async (path) =>
    (await fetch(base + path)).headers.get('x-cache');

  assert.equal(await prime('/products'), 'miss');
  assert.equal(await prime('/products?category=B'), 'miss');
  assert.equal(await prime('/products?category=B'), 'hit');

  const res = await fetch(`${base}/products/2`, { method: 'DELETE' });
  assert.equal(res.status, 200);

  assert.equal((await prime('/products')), 'miss');
  assert.equal((await prime('/products?category=B')), 'miss');
});

