'use strict';

/**
 * Tiny in-process cache with tag-based invalidation.
 *
 * - entries: Map<key, { value, tags }>
 * - tagIndex: Map<tag, Set<key>>
 *
 * Each entry remembers its full tag set so callers can apply fine-grained
 * invalidation policies (see app.js) on top of the raw index.
 */
class TagCache {
  constructor() {
    this.entries = new Map();
    this.tagIndex = new Map();
  }

  get(key) {
    const node = this.entries.get(key);
    return node ? node.value : undefined;
  }

  has(key) {
    return this.entries.has(key);
  }

  /** Tags an entry was stored under ([] for unknown keys). */
  tagsOf(key) {
    const node = this.entries.get(key);
    return node ? node.tags : [];
  }

  set(key, value, tags = []) {
    // If the key already exists, drop its old tag memberships first.
    if (this.entries.has(key)) this.delete(key);
    const frozen = Object.freeze([...new Set(tags)]);
    this.entries.set(key, { value, tags: frozen });
    for (const tag of frozen) {
      let keys = this.tagIndex.get(tag);
      if (!keys) {
        keys = new Set();
        this.tagIndex.set(tag, keys);
      }
      keys.add(key);
    }
    return this;
  }

  delete(key) {
    const node = this.entries.get(key);
    if (!node) return false;
    this.entries.delete(key);
    for (const tag of node.tags) {
      const keys = this.tagIndex.get(tag);
      if (keys) keys.delete(key);
    }
    return true;
  }

  /** Raw key set for a tag (for caller-side snapshots/policies). */
  keysForTag(tag) {
    return this.tagIndex.get(tag);
  }

  clear() {
    this.entries.clear();
    this.tagIndex.clear();
  }
}

module.exports = { TagCache };

