function invalidate(tags) {
  const target = new Set(tags);
  const invalidated = new Set();
  let evicted = 0;
  for (const key of [...cache.entries.keys()]) {
    const entryTags = cache.tagsOf(key);
    const isPureList = entryTags.length === 1 && entryTags[0] === 'products';
    const matchesCategory = entryTags.some(
